import mongoose from "mongoose";

// Personalized week-by-week learning plan generated by the AI service.
const roadmapSchema = new mongoose.Schema(
  {
    user: { type: mongoose.Schema.Types.ObjectId, ref: "User", required: true },
    role: { type: mongoose.Schema.Types.ObjectId, ref: "CareerRole", required: true },
    weeks: [
      {
        week: Number,
        skill: String,
        tasks: [{ title: String, resourceUrl: String, done: { type: Boolean, default: false } }],
      },
    ],
  },
  { timestamps: true }
);

export default mongoose.model("Roadmap", roadmapSchema);
